def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        swapped = False
        for j in range(n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swapped = True
        if not swapped:  # لم يحدث أي تبديل = مرتّبة بالفعل
            break
    return arr

print(bubble_sort([5, 2, 8, 1, 9]))

